<template><article v-if="post"><header class="bg-primary-950 py-14 text-white"><div class="container-page max-w-4xl"><p class="text-sm font-semibold uppercase tracking-wider text-primary-200">{{post.category_name||'Property Guide'}}</p><h1 class="mt-3 text-4xl sm:text-5xl">{{post.title}}</h1><div class="mt-5 flex flex-wrap gap-4 text-sm text-primary-200"><span>By {{post.author}}</span><time v-if="post.published_at">{{formattedDate}}</time></div></div></header><NuxtImg v-if="post.featured_image" :src="post.featured_image" :alt="post.title" class="mx-auto max-h-[560px] w-full max-w-6xl object-cover"/><div class="container-page grid gap-10 py-12 lg:grid-cols-[1fr_280px]"><div class="max-w-3xl"><p class="text-xl font-medium leading-8 text-neutral-700">{{post.excerpt}}</p><div class="prose-content mt-8"><p v-for="(paragraph,index) in paragraphs" :key="index">{{paragraph}}</p></div></div><aside><div class="sticky top-28 rounded-xl bg-primary-50 p-5"><h2 class="text-xl">Interested in a property?</h2><p class="mt-2 text-sm leading-6 text-neutral-600">Explore current prices or arrange a physical inspection with Lexshield.</p><NuxtLink to="/properties" class="btn-primary mt-5 w-full">View Properties</NuxtLink><NuxtLink to="/book-inspection" class="btn-outline mt-2 w-full">Book Inspection</NuxtLink></div></aside></div></article><div v-else-if="!pending" class="container-page py-20"><h1>Article not found</h1></div></template>
<script setup lang="ts">const route=useRoute(),config=useRuntimeConfig();const{data:post,pending}=useAsyncData(`blog-${route.params.slug}`,async()=>{const{data,error}=await useSupabase().from('blog_posts').select('*').eq('slug',String(route.params.slug)).eq('published',true).maybeSingle();if(error)throw error;return data});const paragraphs=computed(()=>String(post.value?.content||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean));const formattedDate=computed(()=>post.value?.published_at?new Intl.DateTimeFormat('en-NG',{dateStyle:'long'}).format(new Date(post.value.published_at)):'');const canonical=computed(()=>`${config.public.siteUrl.replace(/\/$/,'')}/blog/${post.value?.slug||route.params.slug}`);useSeoMeta(()=>({title:post.value?.meta_title||post.value?.title||'Property Guide',description:post.value?.meta_description||post.value?.excerpt||'',ogTitle:post.value?.title,ogDescription:post.value?.excerpt,ogImage:post.value?.featured_image||undefined,ogType:'article',ogUrl:canonical.value}));useHead(()=>({link:[{rel:'canonical',href:canonical.value}],script:post.value?[{type:'application/ld+json',innerHTML:JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:post.value.title,description:post.value.excerpt,image:post.value.featured_image||undefined,datePublished:post.value.published_at,author:{'@type':'Organization',name:'Lexshield Properties Limited'},publisher:{'@type':'Organization',name:'Lexshield Properties Limited'},mainEntityOfPage:canonical.value})}]:[]}))</script>
